import { Component, Input, Output, EventEmitter, OnInit, ViewEncapsulation } from '@angular/core';
import { HelpSupportComponent } from '../../modules/dashboard/components/help-support/help-support.component';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, NavigationEnd } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';
import { ThemeService, ThemeType } from '../../shared/features/home/services/theme.service';
import { SidebarService } from '../../core/services/sidebar.service';
import { Subject } from 'rxjs';
import { RolApiService } from '../../services/rol-api.service';
import { filter, takeUntil } from 'rxjs/operators';


export interface MenuItem {
  name: string;
  icon: string;
  expanded: boolean;
  active: boolean;
  route?: string;
  permission?: string;
  subItems?: SubMenuItem[];
}

export interface SubMenuItem {
  name: string;
  icon: string;
  active: boolean;
  route: string;
  permission?: string;
}

@Component({
  selector: 'app-menu',
  templateUrl: './menu.component.html',
  styleUrls: ['./menu.component.less'],
  standalone: true,
  encapsulation: ViewEncapsulation.None,
  imports: [CommonModule, FormsModule, HelpSupportComponent]
})
export class MenuComponent implements OnInit {
  @Input() isSidebarCollapsed: boolean = false;
  @Input() hasUnreadMessages = false;
  @Output() toggleSidebar = new EventEmitter<void>();
  @Output() toggleHelpSupport = new EventEmitter<void>();

  // Variables del menú
  activeMenu: string = '';
currentTheme: ThemeType = 'light';
 private destroy$ = new Subject<void>();

  // Permisos cacheados del usuario
  private permisosUsuario: Set<string> = new Set();
  private permisosCargados: boolean = false;
// Definición del menú con permisos requeridos
  menuItems: MenuItem[] = [
    {
      name: 'Panel de control',
      icon: '📊',
      expanded: false,
      active: false,
      route: '/dashboard',
      subItems: []
    },
    {
      name: 'Gestionar',
      icon: '⚙️',
      expanded: false,
      active: false,
      subItems: [
        { name: 'Normativas', icon: '📜', active: false, route: '/catalogos', permission: 'catalogos.ver' },
        { name: 'Ciudadanos', icon: '👥', active: false, route: '/personas', permission: 'personas.ver' },
        { name: 'Denuncias', icon: '⚖️', active: false, route: '/denuncias', permission: 'denuncias.ver' },
        { name: 'Intermediación', icon: '🤝', active: false, route: '/intermediaciones', permission: 'intermediaciones.ver' },
        { name: 'Resolución', icon: '✅', active: false, route: '/resoluciones', permission: 'resoluciones.ver' },
        { name: 'Expedientes', icon: '📁', active: false, route: '/expedientes', permission: 'expedientes.ver' }
      ]
    },
    {
      name: 'Personal',
      icon: '👤',
      expanded: false,
      active: false,
      route: '/personal',
      permission: 'personal.ver',
      subItems: []
    },
    {
      name: 'Calendario',
      icon: '📅',
      expanded: false,
      active: false,
      route: '/calendario',
      permission: 'calendario.ver',
      subItems: []
    },
    {
      name: 'Reportes',
      icon: '📈',
      expanded: false,
      active: false,
      route: '/reportes',
      permission: 'reportes.ver',
      subItems: []
    },
    {
      name: 'Seguridad',
      icon: '🔒',
      expanded: false,
      active: false,
      subItems: [
        { name: 'Usuarios', icon: '👥', active: false, route: '/seguridad/usuarios', permission: 'usuarios.ver' },
        { name: 'Acceso', icon: '🔑', active: false, route: '/seguridad/accesos', permission: 'accesos.ver' },
        { name: 'Auditoría', icon: '📋', active: false, route: '/seguridad/auditorias', permission: 'auditoria.ver' }
      ]
    },
    {
      name: 'Backup',
      icon: '💾',
      expanded: false,
      active: false,
      route: '/backup',
      permission: 'backup.ver',
      subItems: []
    },
    {
      name: 'Manuales',
      icon: '📖',
      expanded: false,
      active: false,
      subItems: [
        { name: 'Usuario', icon: '👤', active: false, route: '/manuales/usuario', permission: 'manuales.ver' },
        { name: 'Técnico', icon: '🔧', active: false, route: '/manuales/tecnico', permission: 'manuales.ver' }
      ]
    },
    {
      name: 'AudioVisual',
      icon: '💾',
      expanded: false,
      active: false,
      route: '/audiovisual',
      permission: 'audiovisual.ver',
      subItems: []
    }
  ];

   constructor(
    private authService: AuthService,
     private sidebarService: SidebarService,
     private rolApiService: RolApiService,
     private themeService: ThemeService,
    private router: Router,
  ) {}

 ngOnInit(): void {
    this.themeService.theme$
      .pipe(takeUntil(this.destroy$))
      .subscribe(theme => {
        this.currentTheme = theme;
      });

    this.sidebarService.setCollapsed(this.isSidebarCollapsed);
    this.cargarPermisosUsuario();  // ✅ Cargar permisos al iniciar
    this.checkCurrentRoute();

    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe(() => {
        this.checkCurrentRoute();
      });
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  /**
   * ✅ Cargar permisos usando RolApiService existente
   */
  private cargarPermisosUsuario(): void {
    const user = this.authService.getCurrentUser();
    if (!user || !user.rol_id) {
      // Si no hay usuario, solo mostrar opciones públicas
      this.permisosCargados = true;
      return;
    }

    // ✅ Usar el método existente getPermisosPorRol de RolApiService
    this.rolApiService.getPermisosPorRol(user.rol_id).subscribe({
      next: (response: any) => {
        this.permisosUsuario.clear();

        if (response.success && response.data) {
          // Guardar nombres de permisos
          response.data.forEach((permiso: any) => {
            this.permisosUsuario.add(permiso.nombre);
          });
        }

        // ✅ Administrador (rol_id = 1) tiene todos los permisos automáticamente
        if (user.rol_id === 1) {
          this.permisosUsuario.add('auditoria.ver');
          this.permisosUsuario.add('usuarios.ver');
          this.permisosUsuario.add('accesos.ver');
          this.permisosUsuario.add('personal.ver');
          this.permisosUsuario.add('reportes.ver');
          this.permisosUsuario.add('backup.ver');
        }

        this.permisosCargados = true;
        console.log('✅ Permisos cargados:', Array.from(this.permisosUsuario));
      },
      error: (error) => {
        console.error('Error cargando permisos:', error);
        // Fallback: si es admin, dar permisos básicos
        if (user.rol_id === 1) {
          this.permisosUsuario.add('auditoria.ver');
          this.permisosUsuario.add('usuarios.ver');
        }
        this.permisosCargados = true;
      }
    });
  }

  /**
   * ✅ Verificar si el usuario tiene un permiso específico
   */
  hasPermission(permission?: string): boolean {
    if (!permission) return true;
    if (!this.permisosCargados) return false;

    const user = this.authService.getCurrentUser();
    // Administrador siempre tiene acceso
    if (user?.rol_id === 1) return true;

    return this.permisosUsuario.has(permission);
  }

  /**
   * ✅ Verificar si tiene al menos uno de los permisos
   */
  hasAnyPermission(permissions: string[]): boolean {
    if (!permissions || permissions.length === 0) return true;
    return permissions.some(p => this.hasPermission(p));
  }

  private checkCurrentRoute(): void {
    const currentUrl = this.router.url;
    this.resetAllMenus();

    for (const menuItem of this.menuItems) {
      if (menuItem.route && this.isRouteActive(menuItem.route, currentUrl)) {
        menuItem.active = true;
        this.activeMenu = this.normalizeMenuName(menuItem.name);
        if (menuItem.subItems?.length) menuItem.expanded = true;
        return;
      }

      if (menuItem.subItems) {
        for (const subItem of menuItem.subItems) {
          if (this.isRouteActive(subItem.route, currentUrl)) {
            menuItem.active = true;
            menuItem.expanded = true;
            subItem.active = true;
            this.activeMenu = this.normalizeMenuName(menuItem.name);
            return;
          }
        }
      }
    }

    if (currentUrl === '/' || currentUrl === '/dashboard') {
      const dashboard = this.menuItems.find(i => i.name === 'Panel de control');
      if (dashboard) {
        dashboard.active = true;
        this.activeMenu = 'panel';
      }
    }
  }

  private normalizeMenuName(name: string): string {
    return name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '');
  }

  private resetAllMenus(): void {
    this.menuItems.forEach(item => {
      item.active = false;
      item.subItems?.forEach(sub => sub.active = false);
    });
  }

  private isRouteActive(menuRoute: string, currentUrl: string): boolean {
    if (menuRoute === currentUrl) return true;
    if (menuRoute && currentUrl.startsWith(menuRoute)) {
      const nextChar = currentUrl.charAt(menuRoute.length);
      return nextChar === '' || nextChar === '/' || nextChar === '?' || nextChar === '#';
    }
    return false;
  }

  toggleSidebarHandler(): void {
    this.isSidebarCollapsed = !this.isSidebarCollapsed;
    this.sidebarService.setCollapsed(this.isSidebarCollapsed);
    this.toggleSidebar.emit();
  }

  toggleHelpSupportHandler(): void {
    this.toggleHelpSupport.emit();
  }

  setActiveMenu(menuItem: MenuItem): void {
    this.resetAllMenus();
    menuItem.active = true;
    this.activeMenu = this.normalizeMenuName(menuItem.name);

    if (menuItem.route && (!menuItem.subItems || menuItem.subItems.length === 0)) {
      this.router.navigate([menuItem.route]);
    } else if (menuItem.subItems?.length) {
      menuItem.expanded = true;
    }
  }

  toggleMenuExpand(item: MenuItem): void {
    if (item.subItems?.length) {
      item.expanded = !item.expanded;
      if (!item.expanded && item.active) {
        const hasActiveSub = item.subItems.some(sub => sub.active);
        if (!hasActiveSub) item.active = false;
      }
    } else if (item.route) {
      this.setActiveMenu(item);
    }
  }

  setActiveSubMenu(parent: MenuItem, subIndex: number): void {
    if (!parent.subItems?.[subIndex]) return;

    this.resetAllMenus();
    parent.active = true;
    parent.expanded = true;
    parent.subItems[subIndex].active = true;
    this.activeMenu = this.normalizeMenuName(parent.name);

    const subRoute = parent.subItems[subIndex].route;
    if (subRoute) this.router.navigate([subRoute]);
  }

  // Getters para el template
  getPanelItems(): MenuItem[] {
    return this.menuItems.filter(i => ['Panel de control'].includes(i.name));
  }

  getGestionarItem(): MenuItem | undefined {
    return this.menuItems.find(i => i.name === 'Gestionar');
  }

  getSeguridadItem(): MenuItem | undefined {
    return this.menuItems.find(i => i.name === 'Seguridad');
  }

  getConfiguracionItems(): MenuItem[] {
    return this.menuItems.filter(i =>
      ['Personal', 'Calendario', 'Reportes', 'Configuración', 'Backup'].includes(i.name)
    );
  }

  getDocumentacionItems(): MenuItem[] {
    return this.menuItems.filter(i =>
      ['Documentación', 'Manuales', 'AudioVisual'].includes(i.name)
    );
  }
}
