// src/app/services/rol-api.service.ts
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject, of } from 'rxjs';
import { tap, catchError } from 'rxjs/operators';
import { environment } from '../../environments/environment';
import { NotificationService } from '../core/services/notification/notification.service';

export interface Rol {
  rol_id: number;
  nombre: string;
  descripcion: string;
  fecha_creacion?: string;
}

export interface Permiso {
  permiso_id: number;
  nombre: string;
  descripcion: string;
  fecha_creacion?: string;
}

@Injectable({ providedIn: 'root' })
export class RolApiService {
  private apiUrl = `${environment.apiUrl}`;

  private rolesSubject = new BehaviorSubject<Rol[]>([]);
  roles$ = this.rolesSubject.asObservable();

  private permisosSubject = new BehaviorSubject<Permiso[]>([]);
  permisos$ = this.permisosSubject.asObservable();

  constructor(
    private http: HttpClient,
    private notificationService: NotificationService
  ) {
    this.cargarRoles();
    this.cargarPermisos();
  }

  cargarRoles(): void {
    this.http.get<any>(`${this.apiUrl}/roles`).pipe(
      catchError((error) => {
        console.error('❌ Error cargando roles:', error);
        this.notificationService.showError('Error al cargar roles desde el servidor');
        return of({ data: [] });
      })
    ).subscribe({
      next: (response) => {
        const roles = response.data || response;
        if (Array.isArray(roles)) {
          this.rolesSubject.next(roles);
          console.log('✅ Roles cargados desde backend:', roles.length);
        } else {
          this.rolesSubject.next([]);
        }
      }
    });
  }

  cargarPermisos(): void {
    this.http.get<any>(`${this.apiUrl}/permisos`).pipe(
      catchError((error) => {
        console.error('❌ Error cargando permisos:', error);
        this.notificationService.showError('Error al cargar permisos desde el servidor');
        return of({ data: [] });
      })
    ).subscribe({
      next: (response) => {
        const permisos = response.data || response;
        if (Array.isArray(permisos)) {
          this.permisosSubject.next(permisos);
          console.log('✅ Permisos cargados desde backend:', permisos.length);
        } else {
          this.permisosSubject.next([]);
        }
      }
    });
  }

  // CRUD Roles
  crearRol(rol: Omit<Rol, 'rol_id'>): Observable<any> {
    return this.http.post(`${this.apiUrl}/roles`, rol).pipe(
      tap((response: any) => {
        this.cargarRoles();
        this.notificationService.showSuccess('Rol creado exitosamente');
      }),
      catchError((error) => {
        this.notificationService.showError(error.error?.message || 'Error al crear rol');
        return of(null);
      })
    );
  }

  actualizarRol(id: number, rol: Partial<Rol>): Observable<any> {
    return this.http.put(`${this.apiUrl}/roles/${id}`, rol).pipe(
      tap(() => {
        this.cargarRoles();
        this.notificationService.showSuccess('Rol actualizado exitosamente');
      }),
      catchError((error) => {
        this.notificationService.showError(error.error?.message || 'Error al actualizar rol');
        return of(null);
      })
    );
  }

  eliminarRol(id: number): Observable<any> {
    return this.http.delete(`${this.apiUrl}/roles/${id}`).pipe(
      tap(() => {
        this.cargarRoles();
        this.notificationService.showSuccess('Rol eliminado exitosamente');
      }),
      catchError((error) => {
        this.notificationService.showError(error.error?.message || 'Error al eliminar rol');
        return of(null);
      })
    );
  }

  // CRUD Permisos
  crearPermiso(permiso: Omit<Permiso, 'permiso_id'>): Observable<any> {
    return this.http.post(`${this.apiUrl}/permisos`, permiso).pipe(
      tap(() => {
        this.cargarPermisos();
        this.notificationService.showSuccess('Permiso creado exitosamente');
      }),
      catchError((error) => {
        this.notificationService.showError(error.error?.message || 'Error al crear permiso');
        return of(null);
      })
    );
  }

  actualizarPermiso(id: number, permiso: Partial<Permiso>): Observable<any> {
    return this.http.put(`${this.apiUrl}/permisos/${id}`, permiso).pipe(
      tap(() => {
        this.cargarPermisos();
        this.notificationService.showSuccess('Permiso actualizado exitosamente');
      }),
      catchError((error) => {
        this.notificationService.showError(error.error?.message || 'Error al actualizar permiso');
        return of(null);
      })
    );
  }

  eliminarPermiso(id: number): Observable<any> {
    return this.http.delete(`${this.apiUrl}/permisos/${id}`).pipe(
      tap(() => {
        this.cargarPermisos();
        this.notificationService.showSuccess('Permiso eliminado exitosamente');
      }),
      catchError((error) => {
        this.notificationService.showError(error.error?.message || 'Error al eliminar permiso');
        return of(null);
      })
    );
  }

  // Asignaciones
  getPermisosPorRol(rolId: number): Observable<any> {
    return this.http.get(`${this.apiUrl}/roles/${rolId}/permisos`).pipe(
      catchError((error) => {
        console.error('Error cargando permisos del rol:', error);
        return of({ data: [] });
      })
    );
  }

  asignarPermisos(rolId: number, permisosIds: number[]): Observable<any> {
    return this.http.put(`${this.apiUrl}/roles/${rolId}/permisos`, { permisos_ids: permisosIds }).pipe(
      tap(() => {
        this.notificationService.showSuccess('Permisos asignados exitosamente');
      }),
      catchError((error) => {
        this.notificationService.showError(error.error?.message || 'Error al asignar permisos');
        return of(null);
      })
    );
  }
}
